# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.parsing import parse_span
from hourglass.models import Shift


def _shift(worker, span, day="mon"):
    return Shift(worker, day, parse_span(span))


class TimesheetTests(unittest.TestCase):
    # ---
    def test_busiest_first(self):
        shifts = [
            _shift("Ana", "09:00-10:00"),
            _shift("Bo", "09:00-13:30"),
            _shift("Ana", "10:00-11:00", "tue")
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Bo: 1 shift, 4.5 hours",
                "Ana: 2 shifts, 2.0 hours"
            ]
        )

    # ---
    def test_rounds_to_one_decimal(self):
        shifts = [_shift("Ana", "09:00-09:20")]
        lines = timesheet_lines(shifts)
        self.assertEqual(
            lines, ["Ana: 1 shift, 0.3 hours"]
        )

    # ---
    def test_ties_break_on_name(self):
        lines = timesheet_lines([
            _shift("Bo", "09:00-10:00"),
            _shift("Ana", "09:00-10:00")
        ])
        self.assertTrue(lines[0].startswith("Ana"))

    # ---
    def test_empty_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    # ---
    def test_blank_worker_raises(self):
        for name in ("", "   "):
            shifts = [_shift(name, "09:00-10:00")]
            with self.assertRaises(ValueError):
                timesheet_lines(shifts)
